String
compiler_bundle_ExecutableMessage(ExecutableProblem problem)
{
    if (problem == ExecutableProblem_None) {
        return StringLiteral("none");
    }
    if (problem == ExecutableProblem_Magic) {
        return StringLiteral("not a ZX executable container");
    }
    if (problem == ExecutableProblem_Legacy) {
        return StringLiteral("legacy ZX version contains semantic IR; rebuild with zi2asm --emit zx");
    }
    if (problem == ExecutableProblem_Version) {
        return StringLiteral("unsupported executable ZX version");
    }
    if (problem == ExecutableProblem_Header) {
        return StringLiteral("invalid executable ZX header");
    }
    if (problem == ExecutableProblem_Feature) {
        return StringLiteral("unsupported required executable ZX feature");
    }
    if (problem == ExecutableProblem_Flags) {
        return StringLiteral("invalid executable ZX flags");
    }
    if (problem == ExecutableProblem_RequiredSection) {
        return StringLiteral("unsupported required executable ZX section");
    }
    if (problem == ExecutableProblem_Duplicate) {
        return StringLiteral("duplicate or unordered executable ZX section");
    }
    if (problem == ExecutableProblem_Alignment) {
        return StringLiteral("invalid executable ZX section alignment or padding");
    }
    if (problem == ExecutableProblem_Overlap) {
        return StringLiteral("overlapping executable ZX sections");
    }
    if (problem == ExecutableProblem_Truncated) {
        return StringLiteral("truncated executable ZX container");
    }
    if (problem == ExecutableProblem_Trailing) {
        return StringLiteral("trailing bytes after executable ZX sections");
    }
    if (problem == ExecutableProblem_Limit) {
        return StringLiteral("executable ZX container exceeds a bounded limit");
    }
    if (problem == ExecutableProblem_Output) {
        return StringLiteral("executable ZX output is too short");
    }
    if (problem == ExecutableProblem_Manifest) {
        return StringLiteral("invalid executable ZX manifest");
    }
    if (problem == ExecutableProblem_Entry) {
        return StringLiteral("invalid executable ZX entry function ID");
    }
    if (problem == ExecutableProblem_Capabilities) {
        return StringLiteral("executable ZX requires unsupported host capabilities");
    }
    if (problem == ExecutableProblem_Variant) {
        return StringLiteral("executable ZX requires unsupported native variants");
    }
    if (problem == ExecutableProblem_Assets) {
        return StringLiteral("invalid executable ZX asset section");
    }
    if (problem == ExecutableProblem_Identity) {
        return StringLiteral("executable ZX content identity is invalid");
    }
    return StringLiteral("invalid executable ZX section layout");
}
